/**
 * @method
 * @name scwin.loadForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param lnkDisclsApplSeq subcomNm subcomIsurCd rd_asstTotamtOvr10pctYn lnkDisclsApplApplDd
 * @returns
 * @hidden N
*/
scwin.loadForm = function (lnkDisclsApplSeq, subcomNm, subcomIsurCd, rd_asstTotamtOvr10pctYn, lnkDisclsApplApplDd) {
    /* sdd-asis-lifecycle:begin fn_LoadForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.linkDisclsAppForm || { elements: [] });
    $c.util.getComponent("dma_RegisterReq").set("lnkDisclsApplSeq", lnkDisclsApplSeq);
    $c.util.getComponent('ipt_subcomNm').setValue(subcomNm);
    $c.util.getComponent("dma_RegisterReq").set("subcomIsurCd", subcomIsurCd);
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYn');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === rd_asstTotamtOvr10pctYn) {
            obj[i].checked = true;
        }
    }
    const regexp = /-/g;
    const undashApplDd = lnkDisclsApplApplDd.replace(regexp, "");
    $c.util.getComponent('cal_lnkDisclsApplApplDd').setValue(undashApplDd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.linkDisclsAppForm || { elements: [] });
    if ($c.util.getComponent('ipt_applDd').getValue()>= $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue()) {
        await $c.win.alert('연계공시 적용신청일은  신청일보다 이후 일자 이어야 합니다.');
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue() == null ? '' : String($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue())) === '' || $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("연계공시 적용신청일을 입력해 주세요");
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_subcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_subcomNm').getValue())) === '' || $c.util.getComponent('ipt_subcomNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("상장자회사를 입력해 주세요");
        $c.util.getComponent("ipt_subcomNm").focus();
        return false;
    }
    let aChecked = false;
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYn');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].checked === true) {
            aChecked = true;
            break;
        }
    }
    if (!aChecked) {
        await $c.win.alert("지주회사 자산총액 대비 비중을 선택해 주세요");
        $c.util.getComponent("rd_asstTotamtOvr10pctYn").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param _submitYn
 * @returns
 * @hidden N
*/
scwin.register = async function (_submitYn) {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    const frm = (document.linkDisclsAppForm || { elements: [] });

    if ((String((((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.isurCd", unresolved: "session:" + "isurCd" }; })())($c.session.getUserInfo("isurCd"))) == null ? '' : (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.isurCd", unresolved: "session:" + "isurCd" }; })())($c.session.getUserInfo("isurCd")))).indexOf('$' + '{') >= 0 ? '' : String((((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.isurCd", unresolved: "session:" + "isurCd" }; })())($c.session.getUserInfo("isurCd"))) == null ? '' : (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.isurCd", unresolved: "session:" + "isurCd" }; })())($c.session.getUserInfo("isurCd"))))) === $c.util.getComponent("dma_RegisterReq").get("subcomIsurCd")){
        await $c.win.alert("상장자회사는 신청법인과 동일할 수 없습니다.");			
        return false;
    }

    if("Y" === _submitYn){
        if( $c.util.getComponent("dma_RegisterReq").get("lnkDisclsApplSeq") === "" ){
            await $c.win.alert("제출하고자하는 임시저장 건을 목록에서 선택해주시기 바랍니다.");			
            return false;
        }
    }	 	

    if(!await scwin.chk())
    return;        

    $c.util.getComponent("dma_RegisterReq").set("submitYn", _submitYn);

    if("Y" === _submitYn){
        scwin.loadPop();        		              
    }else{  //임시저장      	        
        $c.util.getComponent("dma_RegisterReq").set("method", 'registerLinkDisclsAppl');
        frm.action='linkDisclsAppl.do';
        await scwin.tx_fn_Register();
    }       

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param type
 * @returns
 * @hidden N
*/
scwin.submit = async function (type) {
    /* sdd-asis-lifecycle:begin fn_Submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ("reg" !== type) {
        await $c.win.alert("잘못된 요청입니다. 다시 시도해주십시요");
        return false;
    }
    const frm = (document.linkDisclsAppForm || { elements: [] });
    $c.util.getComponent("dma_RegisterReq").set("method", 'registerLinkDisclsAppl');
    frm.action = 'linkDisclsAppl.do';
    await scwin.tx_fn_Submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
