*/
scwin.findCompany = async function () {
    /* sdd-asis-lifecycle:begin fn_findCompany — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, { method: "loadInitPage", marketType: "forLink" }));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
